CREATE DATABASE IF NOT EXISTS drc_humanitarian_analytics; USE drc_humanitarian_analytics;
CREATE TABLE IF NOT EXISTS geography(territory_id VARCHAR(20) PRIMARY KEY, province VARCHAR(100) NOT NULL, territory VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS needs_assessment(need_id VARCHAR(20) PRIMARY KEY, date DATE, territory_id VARCHAR(20), province VARCHAR(100), territory VARCHAR(150), sector VARCHAR(80), population_group VARCHAR(100), people_in_need BIGINT, severity_index DECIMAL(4,2), displaced_population BIGINT, assessment_status VARCHAR(40), INDEX idx_needs_geo(territory_id), INDEX idx_needs_date(date), INDEX idx_needs_sector(sector));
CREATE TABLE IF NOT EXISTS response(response_id VARCHAR(20) PRIMARY KEY, date DATE, territory_id VARCHAR(20), province VARCHAR(100), territory VARCHAR(150), sector VARCHAR(80), organization VARCHAR(120), modality VARCHAR(80), people_reached BIGINT, intervention_count INT, response_cost_usd DECIMAL(18,2), INDEX idx_resp_geo(territory_id), INDEX idx_resp_date(date), INDEX idx_resp_sector(sector));
CREATE TABLE IF NOT EXISTS funding(funding_id VARCHAR(20) PRIMARY KEY, date DATE, territory_id VARCHAR(20), province VARCHAR(100), territory VARCHAR(150), sector VARCHAR(80), organization VARCHAR(120), requirements_usd DECIMAL(18,2), received_usd DECIMAL(18,2), funding_source VARCHAR(80), INDEX idx_fund_geo(territory_id), INDEX idx_fund_date(date), INDEX idx_fund_sector(sector));
